const days = (nodes.fetch_forecast.output.days || []);
const units = nodes.fetch_forecast.output.units || 'metric';
const windUnits = units === 'imperial' ? 'mph' : 'km/h';
const complete = days.length === 3 && days.every(d =>
  d && d.date && typeof d.temp_min === 'number' && typeof d.temp_max === 'number' &&
  typeof d.precip_probability === 'number' && typeof d.wind_speed_max === 'number');
if (!complete) {
  return { valid: false, forecast_data: [], trend: '', units: units };
}
const forecast_data = days.map(d => ({
  date: d.date,
  min_temp: d.temp_min,
  max_temp: d.temp_max,
  precipitation_probability_pct: d.precip_probability,
  wind_speed: d.wind_speed_max,
  wind_units: windUnits
}));
const warmest = forecast_data.reduce((a, b) => (b.max_temp > a.max_temp ? b : a));
const coolest = forecast_data.reduce((a, b) => (b.min_temp < a.min_temp ? b : a));
const wettest = forecast_data.reduce((a, b) => (b.precipitation_probability_pct > a.precipitation_probability_pct ? b : a));
const trend = 'Warmest day: ' + warmest.date + ' (max ' + warmest.max_temp + '°' + (units === 'imperial' ? 'F' : 'C') + '). Coolest day: ' + coolest.date + ' (min ' + coolest.min_temp + '°' + (units === 'imperial' ? 'F' : 'C') + '). Wettest day: ' + wettest.date + ' (' + wettest.precipitation_probability_pct + '% precipitation probability).';
return { valid: true, forecast_data: forecast_data, trend: trend, units: units };

config.task:
Write exactly one friendly, conversational paragraph (under 150 words) summarizing this 3-day forecast for {{nodes.geocode.output.name}}, {{nodes.geocode.output.country}}.

FORECAST DATA (use only these numbers):
{{nodes.validate_days.output.forecast_data | json}}

TREND SUMMARY:
{{nodes.validate_days.output.trend}}

Requirements: mention each day's min/max temperature, precipitation probability, and wind speed; end with concrete clothing advice tied to the actual numbers (umbrella only if precipitation probability is 40% or higher; suggest layers, rain jacket, or sunglasses as appropriate); note the resolved location; use {{nodes.validate_days.output.units}} units consistently.
